<?php
require_once '../config/db.php';if(session_status()===PHP_SESSION_NONE)session_start();if(!isset($_SESSION['user_id']))redirect('../index.php');$error='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();
 if(isset($_POST['save_type'])){$id=(int)($_POST['type_id']??0);$name=trim((string)$_POST['type_name']);$kind=in_array($_POST['base_kind'],['product','service','digital'],true)?$_POST['base_kind']:'product';if($name==='')throw new RuntimeException('Type name is required.');if($id)$pdo->prepare('UPDATE item_types SET name=?,base_kind=? WHERE id=?')->execute([$name,$kind,$id]);else $pdo->prepare('INSERT INTO item_types(name,base_kind) VALUES(?,?)')->execute([$name,$kind]);redirect('items.php?saved=type');}
 if(isset($_POST['delete_type'])){$id=(int)$_POST['type_id'];$s=$pdo->prepare('SELECT COUNT(*) FROM items WHERE item_type_id=?');$s->execute([$id]);if($s->fetchColumn())throw new RuntimeException('This type is in use and cannot be deleted.');$pdo->prepare('DELETE FROM item_types WHERE id=?')->execute([$id]);redirect('items.php?saved=type');}
 if(isset($_POST['save_item'])){$id=(int)($_POST['item_id']??0);$typeId=(int)$_POST['item_type_id'];$s=$pdo->prepare('SELECT base_kind FROM item_types WHERE id=?');$s->execute([$typeId]);$kind=$s->fetchColumn();if(!$kind)throw new RuntimeException('Choose a valid item type.');$name=trim((string)$_POST['name']);if($name==='')throw new RuntimeException('Item name is required.');$priceCurrencies=$_POST['price_currency']??[];$priceAmounts=$_POST['price_amount']??[];$prices=[];foreach($priceCurrencies as $i=>$code){$amount=round((float)($priceAmounts[$i]??0),2);if(preg_match('/^[A-Z]{3}$/',$code)&&$amount>=0)$prices[$code]=$amount;}if(!$prices)throw new RuntimeException('Add at least one currency price.');$base=setting($pdo,'base_currency','USD');$unitPrice=$prices[$base]??reset($prices);$vals=[$kind,$typeId,$name,trim((string)$_POST['sku'])?:null,trim((string)$_POST['description']),$unitPrice,(int)$_POST['income_account_id'],$_POST['expense_account_id']!==''?(int)$_POST['expense_account_id']:null,$_POST['tax_rate_id']!==''?(int)$_POST['tax_rate_id']:null];$pdo->beginTransaction();if($id){$pdo->prepare('UPDATE items SET item_type=?,item_type_id=?,name=?,sku=?,description=?,unit_price=?,income_account_id=?,expense_account_id=?,tax_rate_id=? WHERE id=?')->execute([...$vals,$id]);$pdo->prepare('DELETE FROM item_prices WHERE item_id=?')->execute([$id]);}else{$pdo->prepare('INSERT INTO items(item_type,item_type_id,name,sku,description,unit_price,income_account_id,expense_account_id,tax_rate_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute($vals);$id=(int)$pdo->lastInsertId();}$ps=$pdo->prepare('INSERT INTO item_prices(item_id,currency_code,unit_price) VALUES(?,?,?)');foreach($prices as $code=>$amount)$ps->execute([$id,$code,$amount]);$pdo->commit();redirect('items.php?saved=item');}
 }}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException&&$e->getCode()==='23000'?'Type name, SKU, or currency price already exists.':$e->getMessage();}
$types=$pdo->query('SELECT * FROM item_types WHERE is_active=1 ORDER BY base_kind,name')->fetchAll();$currencies=$pdo->query('SELECT code,name,symbol FROM currencies ORDER BY is_base_currency DESC,name')->fetchAll();$income=$pdo->query("SELECT id,account_code,name FROM chart_of_accounts WHERE type='Revenue' AND is_active=1 ORDER BY account_code")->fetchAll();$expense=$pdo->query("SELECT id,account_code,name FROM chart_of_accounts WHERE type='Expense' AND is_active=1 ORDER BY account_code")->fetchAll();$taxes=$pdo->query('SELECT * FROM tax_rates WHERE is_active=1 ORDER BY rate_percentage')->fetchAll();$editId=(int)($_GET['edit']??0);$edit=[];$editPrices=[];if($editId){$s=$pdo->prepare('SELECT * FROM items WHERE id=?');$s->execute([$editId]);$edit=$s->fetch()?:[];$s=$pdo->prepare('SELECT currency_code,unit_price FROM item_prices WHERE item_id=?');$s->execute([$editId]);foreach($s->fetchAll() as $p)$editPrices[$p['currency_code']]=$p['unit_price'];}$items=$pdo->query("SELECT i.*,COALESCE(t.name,i.item_type) type_name,a.name income_name,tr.rate_percentage,GROUP_CONCAT(CONCAT(p.currency_code,':',p.unit_price) ORDER BY p.currency_code SEPARATOR '|') prices FROM items i LEFT JOIN item_types t ON t.id=i.item_type_id LEFT JOIN chart_of_accounts a ON a.id=i.income_account_id LEFT JOIN tax_rates tr ON tr.id=i.tax_rate_id LEFT JOIN item_prices p ON p.item_id=i.id GROUP BY i.id ORDER BY i.name")->fetchAll();require_once 'includes/header.php';require_once 'includes/sidebar.php';$input='mt-1 w-full border rounded-lg px-3 py-2.5';
?>
<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex items-center gap-4 sticky top-0 z-10"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><div><h2 class="text-2xl font-bold">Products & services</h2><p class="text-sm text-slate-500">Custom item types and pricing in multiple currencies</p></div></header><div class="p-5 md:p-8 max-w-7xl mx-auto"><?php if($error):?><div class="bg-rose-50 border border-rose-200 text-rose-800 p-4 rounded-xl mb-5"><?=h($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="bg-emerald-50 border p-4 rounded-xl mb-5">Changes saved.</div><?php endif;?><div class="grid xl:grid-cols-3 gap-7"><div class="space-y-6"><form method="post" class="bg-white border rounded-2xl p-6 space-y-4"><?=csrf_field()?><input type="hidden" name="item_id" value="<?=$editId?>"><h3 class="font-bold text-lg"><?=$editId?'Edit item':'Add item'?></h3><div class="grid grid-cols-2 gap-3"><label class="text-sm">Item type<select name="item_type_id" class="<?=$input?> bg-white"><?php foreach($types as $t):?><option value="<?=$t['id']?>" <?=($edit['item_type_id']??0)==$t['id']?'selected':''?>><?=h($t['name'])?></option><?php endforeach;?></select></label><label class="text-sm">SKU<input name="sku" value="<?=h($edit['sku']??'')?>" class="<?=$input?>"></label></div><label class="block text-sm">Name<input name="name" required value="<?=h($edit['name']??'')?>" class="<?=$input?>"></label><label class="block text-sm">Description<textarea name="description" rows="2" class="<?=$input?>"><?=h($edit['description']??'')?></textarea></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Income account<select name="income_account_id" class="<?=$input?> bg-white"><?php foreach($income as $a):?><option value="<?=$a['id']?>" <?=($edit['income_account_id']??0)==$a['id']?'selected':''?>><?=h($a['account_code'].' '.$a['name'])?></option><?php endforeach;?></select></label><label class="text-sm">Expense account<select name="expense_account_id" class="<?=$input?> bg-white"><option value="">None</option><?php foreach($expense as $a):?><option value="<?=$a['id']?>" <?=($edit['expense_account_id']??0)==$a['id']?'selected':''?>><?=h($a['account_code'].' '.$a['name'])?></option><?php endforeach;?></select></label></div><label class="block text-sm">Default tax<select name="tax_rate_id" class="<?=$input?> bg-white"><option value="">None</option><?php foreach($taxes as $t):?><option value="<?=$t['id']?>" <?=($edit['tax_rate_id']??0)==$t['id']?'selected':''?>><?=h($t['name'])?></option><?php endforeach;?></select></label><div><div class="flex justify-between items-center"><p class="text-sm font-semibold">Currency prices</p><button type="button" id="addPrice" class="brand-text text-sm font-semibold">+ Add currency</button></div><div id="priceRows" class="space-y-2 mt-2"><?php $rows=$editPrices?:[setting($pdo,'base_currency','USD')=>'0.00'];foreach($rows as $code=>$amount):?><div class="price-row grid grid-cols-[1fr_1fr_auto] gap-2"><select name="price_currency[]" class="border rounded-lg px-2 py-2 bg-white"><?php foreach($currencies as $c):?><option value="<?=$c['code']?>" <?=$code===$c['code']?'selected':''?>><?=h($c['code'].' '.$c['symbol'])?></option><?php endforeach;?></select><input name="price_amount[]" type="number" step="0.01" min="0" value="<?=h((string)$amount)?>" class="border rounded-lg px-2 py-2"><button type="button" class="remove-price text-rose-600 px-2">×</button></div><?php endforeach;?></div></div><div class="flex gap-2"><button name="save_item" class="brand-bg text-white rounded-lg px-5 py-2.5 flex-1 font-semibold"><?=$editId?'Update':'Save'?> item</button><?php if($editId):?><a href="items.php" class="border rounded-lg px-4 py-2.5">Cancel</a><?php endif;?></div></form>
<section class="bg-white border rounded-2xl p-6"><h3 class="font-bold">Custom item types</h3><form method="post" class="grid grid-cols-2 gap-2 my-4"><?=csrf_field()?><input name="type_name" required placeholder="e.g. Subscription" class="border rounded px-3 py-2"><select name="base_kind" class="border rounded px-3 py-2 bg-white"><option value="product">Product role</option><option value="service">Service role</option><option value="digital">Digital role</option></select><button name="save_type" class="col-span-2 bg-slate-900 text-white rounded py-2">Create type</button></form><?php foreach($types as $t):?><details class="border rounded-lg p-3 mb-2"><summary class="text-sm font-semibold cursor-pointer"><?=h($t['name'])?> · <span class="text-slate-400"><?=h($t['base_kind'])?></span></summary><form method="post" class="grid grid-cols-2 gap-2 mt-3"><?=csrf_field()?><input type="hidden" name="type_id" value="<?=$t['id']?>"><input name="type_name" value="<?=h($t['name'])?>" class="border rounded px-2"><select name="base_kind" class="border rounded px-2"><?php foreach(['product','service','digital'] as $k):?><option <?=$t['base_kind']===$k?'selected':''?>><?=$k?></option><?php endforeach;?></select><button name="save_type" class="bg-slate-900 text-white rounded">Update</button><button name="delete_type" class="border text-rose-700 rounded">Delete</button></form></details><?php endforeach;?></section></div>
<section class="xl:col-span-2 bg-white border rounded-2xl overflow-hidden h-fit"><div class="p-5 border-b"><h3 class="font-bold text-lg">Item catalogue</h3></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="text-left p-4">Item</th><th class="text-left p-4">Type</th><th class="text-left p-4">Multi-currency prices</th><th class="text-left p-4">Accounting</th><th class="p-4"></th></tr></thead><tbody class="divide-y"><?php foreach($items as $i):?><tr><td class="p-4"><strong><?=h($i['name'])?></strong><p class="text-xs text-slate-500"><?=h($i['sku']?:'No SKU')?></p></td><td class="p-4"><?=h($i['type_name'])?></td><td class="p-4"><?php foreach(explode('|',(string)$i['prices']) as $price):if(!$price)continue;[$code,$amount]=explode(':',$price,2);?><span class="inline-block bg-slate-100 rounded px-2 py-1 mr-1 mb-1"><?=h($code)?> <?=number_format((float)$amount,2)?></span><?php endforeach;?></td><td class="p-4"><?=h($i['income_name'])?><p class="text-xs text-slate-500">Tax <?=h((string)($i['rate_percentage']??0))?>%</p></td><td class="p-4 text-right"><a href="items.php?edit=<?=$i['id']?>" class="brand-text font-semibold">Edit</a></td></tr><?php endforeach;?></tbody></table></div></section></div></div></main>
<template id="priceTemplate"><div class="price-row grid grid-cols-[1fr_1fr_auto] gap-2"><select name="price_currency[]" class="border rounded-lg px-2 py-2 bg-white"><?php foreach($currencies as $c):?><option value="<?=$c['code']?>"><?=h($c['code'].' '.$c['symbol'])?></option><?php endforeach;?></select><input name="price_amount[]" type="number" step="0.01" min="0" value="0.00" class="border rounded-lg px-2 py-2"><button type="button" class="remove-price text-rose-600 px-2">×</button></div></template><script>const priceRows=document.getElementById('priceRows');document.getElementById('addPrice').onclick=()=>priceRows.append(document.getElementById('priceTemplate').content.cloneNode(true));priceRows.addEventListener('click',e=>{if(e.target.classList.contains('remove-price')&&priceRows.children.length>1)e.target.closest('.price-row').remove()});</script><?php require_once 'includes/footer.php';?>
